custom_fields.weather:
[[[
  const w = states[variables.weather];
  if (!w) return '';
  const ic = {
    'clear-night': 'mdi:weather-night', cloudy: 'mdi:cloud-outline',
    fog: 'mdi:weather-fog', hail: 'mdi:weather-hail',
    lightning: 'mdi:weather-lightning', 'lightning-rainy': 'mdi:weather-lightning-rainy',
    partlycloudy: 'mdi:weather-partly-cloudy', pouring: 'mdi:weather-pouring',
    rainy: 'mdi:weather-rainy', snowy: 'mdi:snowflake', 'snowy-rainy': 'mdi:weather-snowy-rainy',
    sunny: 'mdi:white-balance-sunny', windy: 'mdi:weather-windy',
    'windy-variant': 'mdi:weather-windy-variant'
  }[w.state] || 'mdi:cloud-outline';
  const t = Math.round(w.attributes.temperature);
  return `<div style="display:flex;align-items:center;gap:14px">
    <ha-icon icon="${ic}" style="--mdc-icon-size:38px;color:#F5F5F7;opacity:.9"></ha-icon>
    <span style="font-size:38px;font-weight:300;letter-spacing:-0.01em">${isNaN(t) ? '—' : t + '°'}</span></div>`;
]]]

custom_fields.pill:
[[[
  const s = entity ? entity.state : 'unavailable';
  const m = {
    disarmed: ['Disarmed', '#AADCC8', 0], armed_home: ['Armed home', '#AADCC8', 0],
    armed_away: ['Armed away', '#AADCC8', 0], armed_night: ['Armed night', '#AADCC8', 0],
    armed_vacation: ['Armed holiday', '#AADCC8', 0], armed_custom_bypass: ['Armed', '#AADCC8', 0],
    arming: ['Arming…', '#FFCC99', 1], pending: ['Pending…', '#FFCC99', 1],
    disarming: ['Disarming…', '#FFCC99', 1], triggered: ['Alarm', '#FF7878', 1]
  }[s] || ['Unavailable', '#FF7878', 0];
  return `<div style="display:flex;align-items:center;gap:12px;font-size:18px;white-space:nowrap">
    <span style="width:10px;height:10px;border-radius:50%;background:${m[1]};box-shadow:0 0 10px ${m[1]}99;${m[2] ? 'animation:wm-pulse 2s ease-in-out infinite' : ''}"></span>
    <span>${m[0]}</span></div>`;
]]]

custom_fields.msg:
[[[
  const h = new Date().getHours();
  const g = h < 5 ? 'Good night' : h < 12 ? 'Good morning' : h < 18 ? 'Good afternoon' : 'Good evening';
  const s = entity ? String(entity.state) : '';
  const fine = !s || ['unknown', 'unavailable', 'none', 'ok'].includes(s.toLowerCase())
               || /fine|all good|normal/i.test(s);
  const msg = fine ? 'Everything is fine at home' : s.charAt(0).toUpperCase() + s.slice(1);
  return `${g}, ${variables.name}<span style="color:#A1A6B0;margin:0 12px">·</span><span style="color:${fine ? '#A1A6B0' : '#FFCC99'}">${msg}</span>`;
]]]

card.background:
[[[
  const l = states[variables.light], c = states[variables.climate];
  if (l && l.state === 'on')
    return 'radial-gradient(140% 120% at 92% 6%, rgba(255,198,130,0.26) 0%, rgba(214,160,100,0.11) 42%, rgba(255,255,255,0.015) 80%)';
  if (c && (s => s ? (s.attributes.hvac_action || ({heat: 'heating', cool: 'cooling', dry: 'drying', fan_only: 'fan', heat_cool: 'auto', auto: 'auto'})[s.state] || null) : null)(c) === 'heating')
    return 'radial-gradient(140% 120% at 92% 6%, rgba(255,120,120,0.15) 0%, rgba(255,120,120,0.05) 45%, rgba(255,255,255,0.015) 80%)';
  return 'linear-gradient(160deg, rgba(255,255,255,0.028) 0%, rgba(255,255,255,0.012) 100%)';
]]]

custom_fields.deg:
[[[
  const read = (id) => {
    const s = states[id]; if (!s) return null;
    if (id.startsWith('weather.')) return s.attributes.temperature;
    if (id.startsWith('climate.')) return s.attributes.current_temperature;
    const v = parseFloat(s.state); return isNaN(v) ? null : v;
  };
  let v = read(variables.temp); if (v == null) v = read(variables.climate);
  return v == null ? '' : `${Math.round(v)}°`;
]]]

icon.color:
[[[
  if (!entity) return 'rgba(201,204,211,0.34)';
  if (entity.attributes.is_volume_muted || entity.state === 'paused') return '#FFCC99';
  return entity.state === 'playing' ? '#AADCC8' : 'rgba(201,204,211,0.34)';
]]]

[[[
  const a = (s => s ? (s.attributes.hvac_action || ({heat: 'heating', cool: 'cooling', dry: 'drying', fan_only: 'fan', heat_cool: 'auto', auto: 'auto'})[s.state] || null) : null)(entity);
  return a === 'heating' ? '#FF7878' : ['cooling', 'auto', 'drying', 'fan'].includes(a) ? '#AADCC8' : 'rgba(201,204,211,0.34)';
]]]

custom_fields.foot:
[[[
  const w = states[variables.weather], a = states[variables.alarm];
  const ic = { 'clear-night': 'mdi:weather-night', cloudy: 'mdi:cloud-outline', fog: 'mdi:weather-fog', hail: 'mdi:weather-hail', lightning: 'mdi:weather-lightning', 'lightning-rainy': 'mdi:weather-lightning-rainy', partlycloudy: 'mdi:weather-partly-cloudy', pouring: 'mdi:weather-pouring', rainy: 'mdi:weather-rainy', snowy: 'mdi:snowflake', 'snowy-rainy': 'mdi:weather-snowy-rainy', sunny: 'mdi:white-balance-sunny', windy: 'mdi:weather-windy', 'windy-variant': 'mdi:weather-windy-variant' }[w ? w.state : ''] || 'mdi:cloud-outline';
  const t = w ? Math.round(w.attributes.temperature) : NaN;
  const s = a ? a.state : 'unavailable';
  const lbl = { disarmed: 'Disarmed', armed_home: 'Armed home', armed_away: 'Armed away', armed_night: 'Armed night', armed_vacation: 'Armed holiday', armed_custom_bypass: 'Armed', arming: 'Arming…', pending: 'Pending…', disarming: 'Disarming…', triggered: 'Alarm' }[s] || 'Unavailable';
  const col = s === 'triggered' || lbl === 'Unavailable' ? '#FF7878' : ['arming', 'pending', 'disarming'].includes(s) ? '#FFCC99' : '#AADCC8';
  return `<div style="display:flex;align-items:center;gap:28px"><span style="display:flex;align-items:center;gap:10px"><ha-icon icon="${ic}" style="--mdc-icon-size:22px;color:#A1A6B0"></ha-icon>${isNaN(t) ? '—' : t + '°'}</span><span style="display:flex;align-items:center;gap:10px"><span style="width:8px;height:8px;border-radius:50%;background:${col};box-shadow:0 0 8px ${col}99"></span>${lbl}</span></div>`;
]]]
